local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local cs_coroutine = require 'XLua.cs_coroutine'
local Yielders = CS.Engine.Lib.Yielders

local ActivityCrisisContractQuestCell = Class('ActivityCrisisContractQuestCell')
function ActivityCrisisContractQuestCell:__init()

end

function ActivityCrisisContractQuestCell:__delete()

end

function ActivityCrisisContractQuestCell:Awake()
    SetButtonAction(self.controller.transform:Find("BtnRoot"), function()
        local isUnLock = self:CheckIsUnLock()
        if not isUnLock then
            GameUtils.Toast(localize("该事件未到开启时间"))
            return
        end
        UIModule.OpenDialog({ id = Constants.UITypeIds.ActivityCrisisContractLevelListDialog,parameters = { questId = self.data.questId, isRank = false  , preQuest = false }},{{ id = Constants.UITypeIds.ActivityCrisisContractMain}})
    end)
end

function ActivityCrisisContractQuestCell:UpdateContent(data)
    self.data = data
    self.index   = data.index

    local norEnv = CfUtils.GetLuaScr(self.ListNodeNormal,"Game.Activity.CrisisContract.Cell.ActivityCrisisContractQuestNodeCell")
    if not isNull(norEnv) then
        norEnv:RefreshShow(data,1)
    end

    local selEnv = CfUtils.GetLuaScr(self.ListNodeNormalSelect,"Game.Activity.CrisisContract.Cell.ActivityCrisisContractQuestNodeCell")
    if not isNull(selEnv) then
        selEnv:RefreshShow(data,2)
    end
end

function ActivityCrisisContractQuestCell:CheckIsUnLock()
    if checkNumber(self.data.unlockCountdown) > 0 and checkNumber(self.data.unlockCountdown) - os.time() > 0 then
        return false
    end
    return true
end


function ActivityCrisisContractQuestCell:UpdatePosition(position)
    for _, animationState in pairs(self.ItemCell) do
        animationState.normalizedTime = position
        animationState.speed = 0
    end
    self.ItemCell:Play()

    self._position = position

    if checkNumber(self.index) - 1 >= checkNumber(self.ChapterList.currentPosition) and
            checkNumber(self.index) - 1 <= checkNumber(self.ChapterList.currentPosition) + 3 then
        CfUtils.SetActive(self.NorNode, false)
        CfUtils.SetActive(self.Select, true)
        self:UpdateSelectedNode()
    else
        CfUtils.SetActive(self.NorNode, true)
        CfUtils.SetActive(self.Select, false)
    end
end

function ActivityCrisisContractQuestCell:UpdateSelectedNode()
    cs_coroutine.start(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.15))
    end)
end

function ActivityCrisisContractQuestCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActivityCrisisContractQuestCell